using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // ───────────────────────────────────────────────
    //  CalculateTotal – DataRow tests
    // ───────────────────────────────────────────────

    [TestMethod]
    [DataRow(10.00, 1, 0.0,  10.00,  DisplayName = "Single item, no tax")]
    [DataRow(10.00, 2, 0.0,  20.00,  DisplayName = "Two items, no tax")]
    [DataRow(10.00, 1, 0.10, 11.00,  DisplayName = "Single item, 10% tax")]
    [DataRow(25.50, 3, 0.08, 82.62,  DisplayName = "Fractional price with 8% tax")]
    [DataRow(0.00,  5, 0.10, 0.00,   DisplayName = "Zero unit price")]
    [DataRow(99.99, 0, 0.05, 0.00,   DisplayName = "Zero quantity")]
    [DataRow(10.00, 1, 1.0,  20.00,  DisplayName = "100% tax rate (boundary)")]
    public void CalculateTotal_WithDataRow_ReturnsExpected(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expected, result);
    }

    [TestMethod]
    [DataRow(-1.00, 1, 0.10, DisplayName = "Negative unit price throws")]
    public void CalculateTotal_NegativeUnitPrice_Throws(
        double unitPrice, int quantity, double taxRate)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));
    }

    [TestMethod]
    [DataRow(10.00, -1, 0.10, DisplayName = "Negative quantity throws")]
    public void CalculateTotal_NegativeQuantity_Throws(
        double unitPrice, int quantity, double taxRate)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));
    }

    [TestMethod]
    [DataRow(10.00, 1, -0.01, DisplayName = "Tax rate below 0 throws")]
    [DataRow(10.00, 1,  1.01, DisplayName = "Tax rate above 1 throws")]
    public void CalculateTotal_InvalidTaxRate_Throws(
        double unitPrice, int quantity, double taxRate)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));
    }

    // ───────────────────────────────────────────────
    //  ApplyDiscount – DynamicData tests
    // ───────────────────────────────────────────────

    public static IEnumerable<object[]> ApplyDiscountCases
    {
        get
        {
            yield return new object[] { 100.00m, 0m,    100.00m, "No discount" };
            yield return new object[] { 100.00m, 10m,   90.00m,  "10% off" };
            yield return new object[] { 100.00m, 50m,   50.00m,  "50% off" };
            yield return new object[] { 100.00m, 100m,  0.00m,   "100% off (free)" };
            yield return new object[] { 249.99m, 15m,   212.4915m, "Fractional result" };
            yield return new object[] { 0.00m,   25m,   0.00m,   "Zero price with discount" };
        }
    }

    [TestMethod]
    [DynamicData(nameof(ApplyDiscountCases), DynamicDataSourceType.Property,
        DynamicDataDisplayName = nameof(GetApplyDiscountDisplayName))]
    public void ApplyDiscount_WithDynamicData_ReturnsExpected(
        decimal price, decimal discountPercent, decimal expected, string scenario)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result, $"Failed for scenario: {scenario}");
    }

    public static string GetApplyDiscountDisplayName(MethodInfo methodInfo, object[] data)
        => (string)data[3];

    // ───────────────────────────────────────────────
    //  ApplyDiscount – invalid discount boundaries
    // ───────────────────────────────────────────────

    public static IEnumerable<object[]> InvalidDiscountCases
    {
        get
        {
            yield return new object[] { 100.00m, -1m,    "Negative discount" };
            yield return new object[] { 100.00m, 100.01m, "Discount over 100%" };
        }
    }

    [TestMethod]
    [DynamicData(nameof(InvalidDiscountCases), DynamicDataSourceType.Property,
        DynamicDataDisplayName = nameof(GetInvalidDiscountDisplayName))]
    public void ApplyDiscount_InvalidPercent_Throws(
        decimal price, decimal discountPercent, string scenario)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(price, discountPercent),
            $"Expected exception for scenario: {scenario}");
    }

    public static string GetInvalidDiscountDisplayName(MethodInfo methodInfo, object[] data)
        => (string)data[2];
}

